macro.command:
// Basarios Shell - Stamina Drain (MidiQOL 12.4 / Foundry v12 / dnd5e 4.4)
// Actor On-Use via transfer AE: [postActiveEffects]ItemMacro.<this item>
// On a weapon attack hit, reduce each hit target's walk speed by 5 until the start of your next turn.

const macroPass = String(args?.[0]?.macroPass ?? workflow?.macroPass ?? "").toLowerCase();
if (macroPass && !macroPass.includes("postactiveeffects")) return;

const actorDoc = actor ?? workflow?.actor ?? item?.actor ?? item?.parent;
if (!actorDoc) return;

const wf = workflow ?? args?.[0]?.workflow;
if (!wf) return;

const actType = String(wf.activity?.type ?? "").toLowerCase();
const isAttack = actType === "attack" || wf.item?.type === "weapon";
if (!isAttack) return;

const hits = [...(wf.hitTargets ?? [])];
if (!hits.length) return;

const origin = item?.uuid ?? "";
for (const t of hits) {
  const targetActor = t.actor;
  if (!targetActor) continue;
  const stale = targetActor.effects.filter((ef) =>
    ef.origin === origin && /stamina drain/i.test(ef.name ?? ""),
  );
  if (stale.length) {
    await targetActor.deleteEmbeddedDocuments("ActiveEffect", stale.map((e) => e.id));
  }
  await targetActor.createEmbeddedDocuments("ActiveEffect", [{
    name: "Stamina Drain (-5 ft)",
    img: item?.img ?? "mh-icons/material-rune.webp",
    origin,
    transfer: false,
    disabled: false,
    duration: { rounds: 1, turns: null, seconds: null, startTime: null, combat: null, startRound: null, startTurn: null },
    changes: [{ key: "system.attributes.movement.walk", mode: 2, value: "-5", priority: 20 }],
    statuses: [],
    tint: "#ffffff",
    description: "Speed reduced by 5 feet until the start of the attacker's next turn.",
    flags: {
      dae: {
        specialDuration: ["turnStartSource"],
        stackable: "noneName",
        showIcon: true,
      },
    },
  }]);
}
